package cn.minidayz.patcher;
import java.io.*;import java.util.*;import java.util.zip.*;import org.json.*;
/** Individual signed feature ZIPs are the source of truth, including inside a total bundle. */
public final class FeaturePackages {
 static String kind(File f)throws Exception{ZipFile z=new ZipFile(f);try{FilesEx.entries(z);return z.getEntry("module.json")!=null?"module":z.getEntry("feature.json")!=null?"feature":z.getEntry("bundle.json")!=null?"bundle":"";}finally{z.close();}}
 static JSONObject validate(File f,byte[] cert)throws Exception{String k=kind(f);FilesEx.require(k.length()>0,"E_FEATURE_FORMAT");JSONObject m;if(k.equals("bundle")){ZipFile outer=new ZipFile(f);try{if(outer.getEntry("bundle.sig")==null)m=new JSONObject(new String(FilesEx.read(outer.getInputStream(outer.getEntry("bundle.json")),4194304),"UTF-8"));else m=ExternalEngine.signed(f,k,cert);}finally{outer.close();}}else m=ExternalEngine.signed(f,k,cert);FilesEx.require(m.getString("format").equals(k.equals("module")?"mdz-patch/1":"mdz-"+k+"/1"),"E_FEATURE_FORMAT");if(k.equals("module"))FilesEx.require(m.getInt("engine_min")<=PatchEngine.ENGINE,"E_ENGINE_VERSION");if(k.equals("feature")){FilesEx.require(m.getString("engine_id").equals("unityfs-json-155"),"E_ENGINE_ID");String id=m.getString("id");FilesEx.require(id.matches("[a-zA-Z0-9._-]{1,100}"),"E_FEATURE_ID");FilesEx.require(m.getJSONArray("rules").length()>0&&m.getJSONArray("rules").length()<100000,"E_RULE_LIMIT");}return m;}
 static void extract(ZipFile z,ZipEntry e,File f,FilesEx.Watch w)throws Exception{FilesEx.require(e!=null&&e.getSize()>0&&e.getSize()<=536870912,"E_FEATURE_SIZE");FileOutputStream out=new FileOutputStream(f);InputStream in=z.getInputStream(e);try{FilesEx.copy(in,out,w);}finally{out.close();in.close();}}
 public static void importFile(File incoming,File root,byte[] cert,FilesEx.Watch w)throws Exception{File stage=new File(root,"feature-import");FilesEx.deleteTree(stage);stage.mkdirs();File store=new File(root,"features");try{File[] current=store.listFiles();if(current!=null)for(File f:current)if(f.getName().endsWith(".zip")||f.getName().endsWith(".disabled")){FileOutputStream o=new FileOutputStream(new File(stage,f.getName()));InputStream source=new FileInputStream(f);try{FilesEx.copy(source,o,w);}finally{source.close();o.close();}}String k=kind(incoming);JSONObject meta=validate(incoming,cert);if(k.equals("bundle")){ZipFile z=new ZipFile(incoming);try{JSONArray features=meta.getJSONArray("features");FilesEx.require(features.length()>0&&features.length()<100,"E_FEATURE_COUNT");HashSet<String> names=new HashSet<String>();for(int i=0;i<features.length();i++){JSONObject item=features.getJSONObject(i);String path=item.getString("path");FilesEx.require(FilesEx.safeName(path)&&names.add(path),"E_FEATURE_PATH");File f=new File(stage,"bundle-part.pending");extract(z,z.getEntry(path),f,w);FilesEx.require(f.length()==item.getLong("size")&&FilesEx.sha(f,w).equals(item.getString("sha256")),"E_BUNDLE_HASH");storePart(f,stage,cert,w);f.delete();}}finally{z.close();}}else storePart(incoming,stage,cert,w);File combined=new File(root,"features.pending.zip");combine(stage,combined,cert,w);JSONObject assembled=read(combined,cert);File backup=new File(root,"features.previous");FilesEx.deleteTree(backup);if(store.exists())FilesEx.require(store.renameTo(backup),"E_FEATURE_COMMIT");try{FilesEx.require(stage.renameTo(store),"E_FEATURE_COMMIT");FilesEx.atomic(combined,new File(root,"module.zip"));}catch(Exception e){FilesEx.deleteTree(store);backup.renameTo(store);throw e;}FilesEx.deleteTree(backup);}finally{FilesEx.deleteTree(stage);new File(root,"features.pending.zip").delete();}}
 static void storePart(File part,File dir,byte[] cert,FilesEx.Watch w)throws Exception{JSONObject m=validate(part,cert);String k=kind(part);FilesEx.require(!k.equals("bundle"),"E_NESTED_BUNDLE");String name=k.equals("module")?"core":m.getString("id");new File(dir,name+".disabled").delete();File out=new File(dir,name+".zip");if(out.getCanonicalPath().equals(part.getCanonicalPath()))return;FileOutputStream o=new FileOutputStream(out);InputStream in=new FileInputStream(part);try{FilesEx.copy(in,o,w);}finally{o.close();in.close();}}
 static void combine(File dir,File out,byte[] cert,FilesEx.Watch w)throws Exception{File[] parts=dir.listFiles();Arrays.sort(parts);ZipOutputStream z=new ZipOutputStream(new FileOutputStream(out));HashSet<String> blobs=new HashSet<String>();try{z.putNextEntry(new ZipEntry("collection.txt"));z.write("mdz-feature-collection/1".getBytes("UTF-8"));z.closeEntry();for(File f:parts){if(!f.getName().endsWith(".zip"))continue;validate(f,cert);z.putNextEntry(new ZipEntry("parts/"+f.getName()));InputStream in=new FileInputStream(f);try{FilesEx.copy(in,z,w);}finally{in.close();}z.closeEntry();if(kind(f).equals("module")){ZipFile part=new ZipFile(f);try{for(ZipEntry e:FilesEx.entries(part).values())if(e.getName().startsWith("payload/")&&blobs.add(e.getName())){z.putNextEntry(new ZipEntry(e.getName()));InputStream blob=part.getInputStream(e);try{FilesEx.copy(blob,z,w);}finally{blob.close();}z.closeEntry();}}finally{part.close();}}}}finally{z.close();}}
 /** Called again for every inspect/build; no unsigned merged metadata is trusted. */
 public static JSONObject read(File collection,byte[] cert)throws Exception{ZipFile z=new ZipFile(collection);File tempDir=new File(collection.getParentFile(),"verify-parts-"+System.nanoTime());tempDir.mkdirs();try{Map<String,ZipEntry> entries=FilesEx.entries(z);JSONObject core=null;JSONArray features=new JSONArray();HashSet<String> ids=new HashSet<String>();for(ZipEntry e:entries.values())if(e.getName().startsWith("parts/")){FilesEx.require(ids.size()<100,"E_FEATURE_COUNT");File f=new File(tempDir,"part.zip");extract(z,e,f,FilesEx.QUIET);JSONObject m=validate(f,cert);if(kind(f).equals("module")){FilesEx.require(core==null,"E_CORE_DUPLICATE");core=m;}else{FilesEx.require(ids.add(m.getString("id")),"E_FEATURE_DUPLICATE");features.put(m);}f.delete();}FilesEx.require(core!=null,"E_CORE_MISSING: 请先导入总包或原生与隔离基础包");JSONArray allRules=new JSONArray(),display=new JSONArray();String engineId=null;HashSet<String> rulePaths=new HashSet<String>();for(int i=0;i<features.length();i++){JSONObject f=features.getJSONObject(i);if(engineId==null)engineId=f.getString("engine_id");FilesEx.require(engineId.equals(f.getString("engine_id")),"E_ENGINE_CONFLICT");JSONArray rules=f.getJSONArray("rules");JSONArray deps=f.getJSONArray("depends_on");for(int d=0;d<deps.length();d++)FilesEx.require(deps.getString(d).equals("isolation-core")||ids.contains(deps.getString(d)),"E_DEPENDENCY");for(int j=0;j<rules.length();j++){JSONObject rule=rules.getJSONObject(j);FilesEx.require(rulePaths.add(rule.getString("object")+":"+rule.getJSONArray("path").toString()+(rule.has("append")?":"+rule.getString("key_value"):"")),"E_RULE_CONFLICT");allRules.put(rule);}display.put(new JSONObject().put("id",f.getString("id")).put("name",f.getString("name")).put("rules",rules.length()));}core.put("_rules",allRules).put("_features",display);if(engineId!=null)core.put("_engine_id",engineId);return core;}finally{z.close();FilesEx.deleteTree(tempDir);}}
 public static JSONArray inventory(File root)throws Exception{JSONArray result=new JSONArray();File[] files=new File(root,"features").listFiles();if(files==null)return result;Arrays.sort(files);for(File f:files){if(!f.getName().endsWith(".zip")&&!f.getName().endsWith(".disabled"))continue;ZipFile z=new ZipFile(f);try{String k=z.getEntry("module.json")!=null?"module":"feature";JSONObject m=new JSONObject(new String(FilesEx.read(z.getInputStream(z.getEntry(k+".json")),16777216),"UTF-8"));result.put(new JSONObject().put("id",k.equals("module")?"isolation-core":m.getString("id")).put("name",m.getString("name")).put("enabled",f.getName().endsWith(".zip")));}finally{z.close();}}return result;}
 public static void select(File root,java.util.List<String> ids,boolean[] enabled,byte[] cert,FilesEx.Watch w)throws Exception{File store=new File(root,"features"),stage=new File(root,"feature-selection");FilesEx.deleteTree(stage);stage.mkdirs();try{for(File f:store.listFiles()){String name=f.getName();if(!name.endsWith(".zip")&&!name.endsWith(".disabled"))continue;String id=name.substring(0,name.lastIndexOf('.'));int at=ids.indexOf(id);if(at>=0)name=id+(enabled[at]?".zip":".disabled");InputStream in=new FileInputStream(f);FileOutputStream out=new FileOutputStream(new File(stage,name));try{FilesEx.copy(in,out,w);}finally{in.close();out.close();}}File combined=new File(root,"selection.pending.zip");combine(stage,combined,cert,w);read(combined,cert);File backup=new File(root,"features.previous");FilesEx.deleteTree(backup);FilesEx.require(store.renameTo(backup),"E_FEATURE_COMMIT");try{FilesEx.require(stage.renameTo(store),"E_FEATURE_COMMIT");FilesEx.atomic(combined,new File(root,"module.zip"));}catch(Exception e){FilesEx.deleteTree(store);backup.renameTo(store);throw e;}FilesEx.deleteTree(backup);}finally{FilesEx.deleteTree(stage);new File(root,"selection.pending.zip").delete();}}

}
